<?php
require __DIR__.'/lib.php'; gw_require_login(); $db=gw_db();
$period=max(1,min(365,(int)($_GET['days']??30))); $cut=date('Y-m-d H:i:s',time()-$period*86400);
$metrics=[
 'visitors'=>(int)$db->prepare('SELECT COUNT(*) FROM gw_visitors WHERE last_seen>=?')->execute([$cut]),
];
$st=$db->prepare('SELECT COUNT(*) FROM gw_visitors WHERE last_seen>=?');$st->execute([$cut]);$visitorCount=(int)$st->fetchColumn();
$st=$db->prepare('SELECT COUNT(*) FROM gw_visitors WHERE last_seen>=? AND (name IS NOT NULL AND name<>"")');$st->execute([$cut]);$identified=(int)$st->fetchColumn();
$st=$db->prepare('SELECT COUNT(*) FROM gw_events WHERE created_at>=? AND event_type IN ("quote_click","sample_click","whatsapp_click","docs_click")');$st->execute([$cut]);$intent=(int)$st->fetchColumn();
$st=$db->prepare('SELECT COALESCE(MAX(score),0) FROM gw_visitors WHERE last_seen>=?');$st->execute([$cut]);$maxScore=(int)$st->fetchColumn();
$status=$_GET['status']??'';$q=trim($_GET['q']??'');
$sql='SELECT * FROM gw_visitors WHERE last_seen>=?';$args=[$cut];
if($status!==''){ $sql.=' AND status=?';$args[]=$status; }
if($q!==''){ $sql.=' AND (name LIKE ? OR company LIKE ? OR email LIKE ? OR phone LIKE ? OR visitor_key LIKE ?)';$needle='%'.$q.'%';array_push($args,$needle,$needle,$needle,$needle,$needle); }
$sql.=' ORDER BY score DESC,last_seen DESC LIMIT 250';$st=$db->prepare($sql);$st->execute($args);$visitors=$st->fetchAll();
