<section class="hero-admin"><div><p>INTELIGÊNCIA COMERCIAL</p><h1>Visitantes e oportunidades</h1><span>Priorize quem demonstra maior interesse nos produtos da Green World.</span></div><form class="period" method="get"><select name="days" onchange="this.form.submit()"><option value="7" <?=$period===7?'selected':''?>>7 dias</option><option value="30" <?=$period===30?'selected':''?>>30 dias</option><option value="90" <?=$period===90?'selected':''?>>90 dias</option><option value="365" <?=$period===365?'selected':''?>>1 ano</option></select></form></section>
<section class="cards"><article><span>Visitantes</span><strong><?=$visitorCount?></strong><small>No período</small></article><article><span>Leads identificados</span><strong><?=$identified?></strong><small>Com nome cadastrado</small></article><article><span>Ações de intenção</span><strong><?=$intent?></strong><small>WhatsApp, cotação, amostra e docs</small></article><article><span>Maior Lead Score</span><strong><?=$maxScore?></strong><small>Prioridade comercial</small></article></section>
<section class="panel"><div class="panel-head"><div><h2>Pipeline de visitantes</h2><p>Visitantes anônimos ganham histórico e score; você pode identificá-los manualmente quando o contato chegar.</p></div><form class="filters" method="get"><input type="hidden" name="days" value="<?=$period?>"><input name="q" value="<?=gw_e($q)?>" placeholder="Buscar lead..."><select name="status"><option value="">Todos os status</option><?php foreach(gw_statuses() as $s):?><option <?=$status===$s?'selected':''?>><?=gw_e($s)?></option><?php endforeach;?></select><button>Filtrar</button></form></div><div class="table-wrap"><table><thead><tr><th>Lead</th><th>Score</th><th>Status</th><th>Interesse / origem</th><th>Visitas</th><th>Última atividade</th></tr></thead><tbody><?php foreach($visitors as $v):?><tr onclick="location.href='visitor.php?id=<?=$v['id']?>'"><td><b><?=gw_e($v['name'] ?: 'Visitante #'.$v['id'])?></b><small><?=gw_e($v['company'] ?: substr($v['visitor_key'],0,13).'…')?></small></td><td><span class="score <?=$v['score']>=60?'hot':($v['score']>=25?'warm':'')?>"><?=$v['score']?></span></td><td><span class="status"><?=gw_e($v['status'])?></span></td><td><b><?=gw_e($v['last_path'] ?: '—')?></b><small><?=gw_e($v['source'] ?: ($v['first_referrer']?'Referência externa':'Direto'))?></small></td><td><?=$v['visit_count']?></td><td><?=gw_e(date('d/m/Y H:i',strtotime($v['last_seen'])))?></td></tr><?php endforeach;?><?php if(!$visitors):?><tr><td colspan="6" class="empty">Nenhum visitante registrado ainda.</td></tr><?php endif;?></tbody></table></div></section>
